UpdateSourceArgs:
-c "cat > apply-and-start.sh << 'EOS'
#!/bin/bash
set -e
ROOT="$(cd "$(dirname "$0")" && pwd)"
CONF_ABS="$ROOT/config/default.conf"
SETTINGS="$ROOT/config/amp-settings.cfg"
JAVA=/usr/lib/jvm/temurin-11-jdk-amd64/bin/java
# Path relative to 2009scape/Server (server resolves config relative to cwd)
CONF_REL="../../config/default.conf"

if [ ! -f "$CONF_ABS" ]; then
  echo "ERROR: $CONF_ABS missing"
  exit 1
fi

if [ -f "$SETTINGS" ]; then
  while IFS='=' read -r KEY VAL || [ -n "$KEY" ]; do
    KEY=$(echo "$KEY" | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
    VAL=$(echo "$VAL" | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
    [ -z "$KEY" ] && continue
    case "$KEY" in \#*) continue ;; esac

    SEC=""; TKEY=""
    case "$KEY" in
      WorldName) SEC=world; TKEY=name ;;
      WorldId) SEC=world; TKEY=world_id ;;
      Members) SEC=world; TKEY=members ;;
      Activity) SEC=world; TKEY=activity ;;
      Pvp) SEC=world; TKEY=pvp ;;
      WildPvp) SEC=world; TKEY=wild_pvp_enabled ;;
      EnableBots) SEC=world; TKEY=enable_bots ;;
      Debug) SEC=world; TKEY=debug ;;
      Dev) SEC=world; TKEY=dev ;;
      XpRates) SEC=world; TKEY=xp_rates ;;
      Ironman) SEC=world; TKEY=ironman ;;
      PlayerCommands) SEC=world; TKEY=player_commands ;;
      IWantToCheat) SEC=world; TKEY=i_want_to_cheat ;;
      SkillcapePerks) SEC=world; TKEY=skillcape_perks ;;
      SecondBank) SEC=world; TKEY=second_bank ;;
      EnableGlobalChat) SEC=world; TKEY=enable_global_chat ;;
      LogLevel) SEC=server; TKEY=log_level ;;
      SecretKey) SEC=server; TKEY=secret_key ;;
      UseAuth) SEC=server; TKEY=use_auth ;;
      PersistAccounts) SEC=server; TKEY=persist_accounts ;;
      NoAuthDefaultAdmin) SEC=server; TKEY=noauth_default_admin ;;
      WatchdogEnabled) SEC=server; TKEY=watchdog_enabled ;;
      ConnectivityTimeout) SEC=server; TKEY=connectivity_timeout ;;
      PreloadMap) SEC=server; TKEY=preload_map ;;
      DatabaseName) SEC=database; TKEY=database_name ;;
      DatabaseUsername) SEC=database; TKEY=database_username ;;
      DatabasePassword) SEC=database; TKEY=database_password ;;
      DatabaseAddress) SEC=database; TKEY=database_address ;;
      DatabasePort) SEC=database; TKEY=database_port ;;
      *) continue ;;
    esac

    case "$VAL" in true|True|TRUE) VAL=true ;; false|False|FALSE) VAL=false ;; esac
    case "$VAL" in true|false|[0-9]*) Q="$VAL" ;; *) Q="\"$VAL\"" ;; esac

    awk -v sec="$SEC" -v key="$TKEY" -v q="$Q" '
      BEGIN { insec=0 }
      /^\[/ { insec = ($0 == "[" sec "]") }
      insec && $0 ~ ("^[[:space:]]*" key "[[:space:]]*=") {
        print key " = " q
        next
      }
      { print }
    ' "$CONF_ABS" > "$CONF_ABS.tmp" && mv "$CONF_ABS.tmp" "$CONF_ABS"
  done < "$SETTINGS"
  echo "Applied settings from amp-settings.cfg"
fi

cd "$ROOT/2009scape/Server"
exec "$JAVA" -Dnashorn.args=--no-deprecation-warning -jar ../builddir/server.jar "$CONF_REL"
EOS
chmod +x apply-and-start.sh
echo Installed apply-and-start.sh"
